INSERT INTO historia (id, pergunta, tipo, opcao_a, opcao_b, opcao_c, opcao_d, resposta_correta, explicacao) VALUES
  (1, '/criadas/ De acordo com o texto, quais palavras atuais têm etimologia grega?', 'multipla', 'enigma, tecnologia, época, simpatia e história', 'república, salário, senado e cônsul', 'gladiador, cesaropapismo e câmara', 'tessela, anfiteatro e monoteísmo', 'a', 'O texto cita na introdução que as palavras enigma, tecnologia, época, simpatia e história são heranças da linguística grega.'),
  (2, '/criadas/ Na Grécia Antiga, os deuses possuíam formas humanas e eram mortais.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'errado', 'Os deuses eram antropomorfos (tinham forma humana), mas eram imortais.'),
  (3, '/criadas/ Como os sacerdotes gregos eram tratados pela comunidade?', 'multipla', 'Como reis divinos com poder absoluto', 'Como simples cidadãos', 'Como escravos do templo', 'Como generais do exército', 'b', 'O livro relata que os sacerdotes eram tratados na comunidade como simples cidadãos.'),
  (4, '/criadas/ O Templo Erecteion, localizado na Acrópole de Atenas, foi dedicado a quais deuses?', 'multipla', 'Zeus e Hera', 'Atenas e Poseidon', 'Ares e Afrodite', 'Hades e Hermes', 'b', 'A legenda da imagem destaca que o Erecteion era dedicado aos deuses Atenas e Poseidon.'),
  (5, '/criadas/ Segundo o texto, quem é a deusa grega do amor e da beleza?', 'multipla', 'Ártemis', 'Deméter', 'Afrodite', 'Hera', 'c', 'O texto lista Afrodite como a deusa do amor e da beleza.'),
  (6, '/criadas/ Na mitologia grega, Dionísio era cultuado como o deus:', 'multipla', 'Da guerra', 'Do Sol e da medicina', 'Do vinho e da fertilidade', 'Dos mares e tempestades', 'c', 'O texto define Dionísio como deus do vinho e da fertilidade.'),
  (7, '/criadas/ Dois importantes deuses não habitavam o Monte Olimpo: Poseidon e Hades.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'Poseidon habitava as profundezas do oceano e Hades as profundezas da Terra.'),
  (8, '/criadas/ Qual herói grego matou o minotauro no Palácio de Cnossos?', 'multipla', 'Teseu', 'Édipo', 'Heracles', 'Aquiles', 'a', 'Teseu matou o minotauro no Palácio de Cnossos, em Creta.'),
  (9, '/criadas/ Quem decifrou o enigma da esfinge, de acordo com o texto?', 'multipla', 'Hércules', 'Édipo', 'Teseu', 'Péricles', 'b', 'O herói grego que decifrou o enigma da esfinge foi Édipo.'),
  (10, '/criadas/ Os Jogos Olímpicos eram festas religiosas realizadas em honra a qual divindade?', 'multipla', 'Apolo', 'Poseidon', 'Zeus', 'Ares', 'c', 'As competições olímpicas eram realizadas de quatro em quatro anos em honra a Zeus.'),
  (11, '/criadas/ Nos Jogos Píticos, as competições celebravam o deus Apolo com provas atléticas e artísticas.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'Nos Jogos Píticos, o deus Apolo era venerado com disputas esportivas e manifestações de música e poesia.'),
  (12, '/criadas/ Qual historiador grego participou da Guerra do Peloponeso e escreveu sobre ela?', 'multipla', 'Xenofonte', 'Tucídides', 'Tales', 'Anaximandro', 'b', 'Tucídides escreveu sobre a história da Guerra do Peloponeso, conflito do qual foi participante.'),
  (13, '/criadas/ No século V a.C., para suprir a falta de mão de obra, os atenienses compraram escravos vindos:', 'multipla', 'De Roma', 'Da Germânia', 'Do Oriente', 'Da Britânia', 'c', 'O texto afirma que a saída encontrada foi comprar escravos no Oriente em grande quantidade.'),
  (14, '/criadas/ Na Grécia Antiga, alguns escravizados atuavam como pedagogos, cuidando da educação moral das crianças.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'Além de atividades braçais, os escravizados acompanhavam as crianças às palestras e cuidavam da sua educação moral.'),
  (15, '/criadas/ Os conflitos entre gregos e persas ficaram conhecidos como Guerras Médicas porque os gregos chamavam os persas de medos.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'O livro especifica que os persas eram chamados de medos pelos gregos.'),
  (16, '/criadas/ Na primeira fase das Guerras Médicas, o imperador persa derrotado na Batalha de Maratona foi:', 'multipla', 'Xerxes', 'Dario I', 'Ciro', 'Alexandre', 'b', 'Dario I liderou a primeira invasão e foi derrotado na Batalha de Maratona.'),
  (17, '/criadas/ Em qual batalha naval os atenienses venceram os persas pela estratégia de guerra superior?', 'multipla', 'Batalha das Termópilas', 'Batalha de Salamina', 'Batalha de Queroneia', 'Batalha de Actium', 'b', 'A Batalha de Salamina consolidou a vitória estratégica dos gregos sobre os persas no mar.'),
  (18, '/criadas/ Qual tratado pôs fim às Guerras Médicas reconhecendo o domínio grego sobre o Mar Egeu?', 'multipla', 'Tratado de Susa', 'Tratado de Delos', 'Tratado de Versalhes', 'Tratado de Queroneia', 'a', 'O conflito teve fim com a assinatura do Tratado de Susa.'),
  (19, '/criadas/ Qual aliança militar foi criada por Esparta para rivalizar com a Confederação de Delos?', 'multipla', 'Liga Helênica', 'Liga do Peloponeso', 'Liga Macedônica', 'Tetrarquia', 'b', 'Esparta e cidades aliadas criaram a Liga do Peloponeso.'),
  (20, '/criadas/ A Guerra do Peloponeso durou 27 anos (431 a.C. a 404 a.C.) e terminou com a vitória de:', 'multipla', 'Atenas', 'Tebas', 'Esparta', 'Pérsia', 'c', 'Esparta venceu o conflito, que gerou o enfraquecimento geral do mundo grego.'),
  (21, '/criadas/ As trirremes foram as principais embarcações utilizadas na Guerra do Peloponeso.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'O texto e a legenda destacam que a trirreme era a principal embarcação empregada.'),
  (22, '/criadas/ Na Batalha de Queroneia (338 a.C.), Filipe II da Macedônia venceu as tropas de quais pólis?', 'multipla', 'Esparta e Corinto', 'Tebas e Atenas', 'Mileto e Creta', 'Roma e Cartago', 'b', 'Filipe II venceu os exércitos de Tebas e Atenas na Batalha de Queroneia.'),
  (23, '/criadas/ Alexandre, o Grande, foi educado e recebeu formação intelectual de qual famoso filósofo?', 'multipla', 'Sócrates', 'Platão', 'Aristóteles', 'Anaximandro', 'c', 'O texto confirma que Alexandre era aluno do filósofo Aristóteles.'),
  (24, '/criadas/ Qual cidade se revoltou após a morte de Filipe II e foi completamente destruída por Alexandre?', 'multipla', 'Atenas', 'Esparta', 'Tebas', 'Corinto', 'c', 'Alexandre destruiu a cidade de Tebas para servir de exemplo a outras rebeliões.'),
  (25, '/criadas/ O que significa a palavra helenizar no contexto histórico?', 'multipla', 'Viver como os persas', 'Viver como os gregos', 'Viver como os egípcios', 'Viver sem religião', 'b', 'O texto explica que helenizar significa viver como os gregos.'),
  (26, '/criadas/ O helenismo foi a fusão da cultura grega com as tradições do Egito, Mesopotâmia e Pérsia.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'O helenismo nasceu do encontro e da mistura cultural das pólis gregas com o Oriente.'),
  (27, '/criadas/ Segundo Plutarco, quantas cidades Alexandre, o Grande, fundou com o nome de Alexandria?', 'multipla', 'Doze cidades', 'Trinta cidades', 'Cinquenta cidades', 'Setenta cidades', 'd', 'O texto relata que Alexandre fundou setenta cidades com o nome de Alexandria.'),
  (28, '/criadas/ O que eram os asklepieia que se espalharam pelo mundo helenístico?', 'multipla', 'Templos de sacrifício', 'Instituições hospitalares', 'Teatros ao ar livre', 'Portos mercantis', 'b', 'Eram instituições hospitalares em honra ao deus da Medicina.'),
  (29, '/criadas/ A história de Roma é dividida tradicionalmente em três períodos: Realeza, República e Império.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'O texto descreve que a cronologia romana se divide em monarquia (realeza), república e império.'),
  (30, '/criadas/ Segundo a tradição, quantos reis governaram Roma durante a fase da Realeza?', 'multipla', 'Três', 'Cinco', 'Sete', 'Dez', 'c', 'Roma teve sete reis na realeza, sendo Rômulo o primeiro.'),
  (31, '/criadas/ Quem foi o último rei etrusco da fase da monarquia romana?', 'multipla', 'Sérvio Túlio', 'Tarquínio Prisco', 'Tarquínio, o Soberbo', 'Numa Pompílio', 'c', 'Tarquínio, o Soberbo, governou até a expulsão dos reis e proclamação da república.'),
  (32, '/criadas/ Na República romana, o poder executivo e militar era exercido por:', 'multipla', 'Dois cônsules', 'Um único rei', 'Quatro tribunos', 'Dez senadores', 'a', 'O poder passou a ser exercido por dois cônsules eleitos anualmente.'),
  (33, '/criadas/ O termo república provém do latim res publica, que significa literalmente:', 'multipla', 'Poder supremo', 'Coisa do povo', 'Lei dos deuses', 'Governo forte', 'b', 'O livro explica que res é coisa e publica do povo, formando coisa do povo.'),
  (34, '/criadas/ Qual cargo no Senado foi criado para representar os plebeus após suas reivindicações?', 'multipla', 'Ditador', 'Pontífice Máximo', 'Tribuno da Plebe', 'Patrício Maior', 'c', 'Foi concedida a escolha de um representante chamado Tribuno da Plebe.'),
  (35, '/criadas/ O orador Élio Aristides destacou a grandiosidade de Roma pelo fluxo comercial contínuo no Mediterrâneo.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'O texto transcreve o relato de Élio Aristides sobre as mercadorias que afluíam a Roma de todas as terras.'),
  (36, '/criadas/ A palavra gladiador é derivada de gladius, que correspondia a:', 'multipla', 'Um escudo redondo', 'Uma espada curta', 'Uma rede de pesca', 'Um elmo de bronze', 'b', 'O termo provém da espada curta utilizada pelos lutadores, o gladius.'),
  (37, '/criadas/ Como surgiram os cavaleiros na sociedade romana?', 'multipla', 'Plebeus que enriqueceram e podiam comprar um cavalo', 'Patrícios empobrecidos pelo comércio', 'Escravos libertos pelo imperador', 'Senadores que serviam ao exército', 'a', 'Eram plebeus que enriqueceram e tinham recursos para adquirir um cavalo.'),
  (38, '/criadas/ Qual tribuno da plebe propôs a Lei Agrária em 133 a.C. e foi assassinado em um tumulto?', 'multipla', 'Caio Graco', 'Tibério Graco', 'Espártaco', 'Cícero', 'b', 'Tibério Graco propôs a divisão de terras aos lavradores e foi assassinado.'),
  (39, '/criadas/ A Lei Frumentária (Lei do Trigo), proposta por Caio Graco, garantia aos pobres:', 'multipla', 'Trigo de graça em templos', 'Trigo por um preço menor', 'Proibição de plantio fora de Roma', 'Obrigação de entregar trigo ao Senado', 'b', 'A lei dava aos mais necessitados o direito de comprar trigo por um preço reduzido.'),
  (40, '/criadas/ O general romano Mário profissionalizou o exército ao criar o salário para os soldados.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'Mário instituiu o soldo/salário, transformando a força voluntária em exército profissional.'),
  (41, '/criadas/ A palavra salário provém de salarium argentum, que remete ao pagamento de soldados feito com:', 'multipla', 'Ouro em barra', 'Trigo e pão', 'Sal', 'Prata estrangeira', 'c', 'O sal era uma mercadoria valiosa e servia como forma de pagamento aos soldados.'),
  (42, '/criadas/ O líder da grande revolta de cerca de 100 mil escravos ocorrida entre 73 e 71 a.C. foi:', 'multipla', 'Espártaco', 'Catilina', 'Lêntulo Batiato', 'Lépido', 'a', 'Espártaco liderou a revolta a partir da escola de gladiadores de Cápua.'),
  (43, '/criadas/ Quem formou o Primeiro Triunvirato em Roma?', 'multipla', 'Otávio, Marco Antônio e Lépido', 'Crasso, Pompeu e Júlio César', 'Mário, Sila e Cícero', 'Augusto, Tibério e Nero', 'b', 'O I Triunvirato foi composto pelos generais Crasso, Pompeu e Júlio César.'),
  (44, '/criadas/ Na Batalha de Actium (31 a.C.), Otávio derrotou as tropas de Marco Antônio e da rainha Cleópatra.', 'certo_errado', 'Certo', 'Errado', NULL, NULL, 'certo', 'A vitória de Otávio em Actium consolidou seu poder e marcou o início do império.'),
  (45, '/criadas/ O imperador Diocleciano criou a Tetrarquia em 284 d.C., composta por quantos chefes militares?', 'multipla', 'Dois chefes', 'Três chefes', 'Quatro chefes', 'Cinco chefes', 'c', 'A Tetrarquia foi a divisão do governo entre quatro líderes militares.'),
  (46, '/criadas/ Qual documento emitido por Constantino em 313 d.C. concedeu liberdade de culto aos cristãos?', 'multipla', 'Édito de Milão', 'Tratado de Susa', 'Lei das Doze Tábuas', 'Corpus Juris Civilis', 'a', 'O Édito de Milão estabeleceu tolerância religiosa no império.'),
  (47, '/criadas/ Em 395 d.C., o imperador Teodósio dividiu o Império Romano entre seus dois filhos, criando:', 'multipla', 'Império do Norte e Império do Sul', 'Império Romano do Ocidente e Império Romano do Oriente', 'Império Latino e Império Grego', 'Império de Roma e Império de Alexandria', 'b', 'Teodósio oficializou o cristianismo e dividiu o império em Ocidente e Oriente.'),
  (48, '/criadas/ A capital do Império Bizantino, Constantinopla, foi erguida no local da antiga colônia grega de:', 'multipla', 'Esparta', 'Bizâncio', 'Tebas', 'Corinto', 'b', 'Constantino escolheu a antiga colônia grega de Bizâncio para fundar sua capital.'),
  (49, '/criadas/ O que era o cesaropapismo praticado no Império Bizantino?', 'multipla', 'Submissão da Igreja ao imperador, chefe do Estado e da fé', 'Eleição democrática dos bispos pelo povo', 'Separação total entre religião e política', 'Proibição do cristianismo na capital', 'a', 'O cesaropapismo subordinava as decisões da Igreja bizantina à autoridade do imperador.'),
  (50, '/criadas/ Como ficou conhecida a divisão de 1054 entre a Igreja Católica Romana e a Igreja Ortodoxa?', 'multipla', 'Cisma do Oriente', 'Revolta de Espártaco', 'Paz de Susa', 'Edito de Tolerância', 'a', 'O Cisma do Oriente selou a ruptura entre a Igreja de Roma e a Igreja Ortodoxa.');